	@Test
	void orderedIntegerTagBitReflectsTheNeighborDomain() {
		LmdbAdjacencyArena arena = newArena(1 << 20);
		LmdbAdjacencyArenaCatalog catalog = newCatalog(arena);
		LmdbAdjacencyContextCatalog contexts = LmdbAdjacencyContextCatalog.base(arena, new long[0]);

		long orderedNeighbor = ValueIds.createId(ValueIds.T_ORD_INTEGER, ValueIds.ORDERED_BIAS + 42);
		long referenceNeighbor = ValueIds.createId(ValueIds.T_URI, 42);
		assertThat(ValueIds.isOrderedInteger(orderedNeighbor)).isTrue();
		assertThat(ValueIds.isOrderedInteger(referenceNeighbor)).isFalse();

		long orderedRef = LmdbAdjacencyRunCodec.encode(source(new long[][] { { orderedNeighbor, 0 } }), contexts,
				arena);
		long referenceRef = LmdbAdjacencyRunCodec.encode(source(new long[][] { { referenceNeighbor, 0 } }), contexts,
				arena);

		assertThat(LmdbAdjacencyRunCodec.orderedIntegerDomain(catalog, catalog.packHandle(0, orderedRef))).isTrue();
		assertThat(LmdbAdjacencyRunCodec.orderedIntegerDomain(catalog, catalog.packHandle(0, referenceRef))).isFalse();

		// an inlined double neighbor is never an ordered integer
		long doubleNeighbor = Double.doubleToLongBits(3.5) | 1L;
		assertThat(ValueIds.isDouble(doubleNeighbor)).isTrue();
		long doubleRef = LmdbAdjacencyRunCodec.encode(source(new long[][] { { doubleNeighbor, 0 } }), contexts, arena);
		assertThat(LmdbAdjacencyRunCodec.orderedIntegerDomain(catalog, catalog.packHandle(0, doubleRef))).isFalse();
	}

