	@Test
	void reusableRunCursorCopiesPartialSmallAndBlockRuns() {
		LmdbAdjacencyArena arena = newArena(1 << 20);
		LmdbAdjacencyArenaCatalog catalog = newCatalog(arena);
		LmdbAdjacencyRunCodec.RunCursor cursor = new LmdbAdjacencyRunCodec.RunCursor();

		for (int degree : new int[] { 6, 130 }) {
			long[][] pairs = new long[degree][2];
			for (int i = 0; i < degree; i++) {
				pairs[i][0] = 1_000L + i * 11L;
				pairs[i][1] = i % 3 == 0 ? 0 : 10_000L + i;
			}
			LmdbAdjacencyContextCatalog contexts = catalogFor(arena, pairs);
			long ref = LmdbAdjacencyRunCodec.encode(source(pairs), contexts, arena);
			long handle = catalog.packHandle(0, ref);

			LmdbAdjacencyRunCodec.resolve(catalog, handle, cursor);
			assertThat(cursor.edgeCount()).isEqualTo(degree);

			int from = 2;
			int length = degree - 3;
			long[] neighbors = new long[length + 2];
			long[] rawContexts = new long[length + 2];
			int copied = LmdbAdjacencyRunCodec.copy(contexts, cursor, from, length, neighbors, 1, rawContexts, 1);

			assertThat(copied).isEqualTo(length);
			for (int i = 0; i < copied; i++) {
				assertThat(neighbors[i + 1]).isEqualTo(pairs[from + i][0]);
				assertThat(rawContexts[i + 1]).isEqualTo(pairs[from + i][1]);
			}
		}
	}

